import sys
from valid_names import valid_names

def write_results_to_file(result, output_file):
    """ Write the categorized results into a new file """
    try:
        with open(output_file, "w", encoding="utf-8") as file_out:
            for category, details in result.items():
                file_out.write(f"{category}: {details['count']} mots\n")
                file_out.write("[" + '", "'.join(details['words']) + "]\n\n")
        print(f"Les résultats ont été écrits avec succès dans {output_file}.")
    except Exception as e:
        print(f"Une erreur s'est produite lors de l'écriture dans le fichier : {e}")

def categorize_words(word_list, valid_names):
    """ Categorize words into specific groups based on criteria and count elements in each category. """
    categorized = {
        "valid_names": {"words": [], "count": 0},
        "start_or_end_with_dash": {"words": [], "count": 0},
        "contains_dash": {"words": [], "count": 0},
        "contains_digits": {"words": [], "count": 0},
        "stuck_words": {"words": [], "count": 0},
        "others": {"words": [], "count": 0}
    }

    for word in word_list:
        word = word.strip()  # Clean up whitespace
        
        if word in valid_names:
            categorized["valid_names"]["words"].append(word)
        elif any(char.isdigit() for char in word):
            categorized["contains_digits"]["words"].append(word)
        elif word.startswith('-') or word.endswith('-'):
            categorized["start_or_end_with_dash"]["words"].append(word)
        elif '-' in word:  # Check for dashes elsewhere but avoid duplicates
            if word not in categorized["start_or_end_with_dash"]["words"]:
                categorized["contains_dash"]["words"].append(word)
        elif len(word) > 10:  # Words with more than 10 characters
            categorized["stuck_words"]["words"].append(word)
        else:
            categorized["others"]["words"].append(word)

    # Calculate counts for each category
    for category in categorized:
        categorized[category]["count"] = len(categorized[category]["words"])
    
    return categorized


